import json

center = 8
size = 17
grid = [[0] * size for _ in range(size)]

# 2s: Triangle from top-center to edges
for r in range(center + 1):
    c_lo = center - r
    c_hi = center + r
    grid[r][c_lo] = 2
    grid[r][c_hi] = 2

# Middle pattern: 1s at center ± (center - r) for rows where center-2 to center
for r in range(max(0, center - 2), center):
    d = center - r
    if d <= center:
        grid[r][center - d] = 1
        grid[r][center + d] = 1

# Bottom pattern: 1s extending from corners
for r in range(center + 1, size):
    dr = size - 1 - r
    if dr > 0:
        c_lo = center - dr
        c_hi = center + dr
        if c_lo >= 0 and c_hi < size:
            if grid[r][c_lo] == 0:
                grid[r][c_lo] = 1
            if grid[r][c_hi] == 0:
                grid[r][c_hi] = 1

action = {"action": "submit", "grid": grid}
