import json

# Final attempt: Diamond-based 1s pattern
center = 8
size = 17
grid = [[0] * size for _ in range(size)]

# 2s: Triangle from top-center to edges
for r in range(center + 1):
    grid[r][center - r] = 2
    grid[r][center + r] = 2

# 1s: Diamond centered at (center, center)
# 1s where Manhattan distance from center is even and in [2, 14]
for r in range(size):
    for c in range(size):
        if grid[r][c] == 0:
            manhattan = abs(r - center) + abs(c - center)
            if manhattan % 2 == 0 and 2 <= manhattan <= size - 2:
                grid[r][c] = 1

